-- Backend Engineering ("The Fracture") post-game world -- "Database Mastery" content.
-- Optional Arc IX mastery module (world-be-database-mastery, already inserted by the
-- spine migration). Pure Postgres-internals skill content, no ongoing mystery thread --
-- The Fracture was resolved in Act 32. 1 campaign, 2 operations, 12 missions
-- (11 lessons + boss), following the same campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern as every prior Act.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be-database-mastery', 'world-be-database-mastery', 'database-mastery', 'Mastery C - Database Internals', 'The Fracture is closed. What''s left standing under every mission you ran to close it is a database neither this campaign nor Act 32 ever fully opened up -- and that''s exactly where Arc IX starts.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be-database-mastery-1', 'campaign-be-database-mastery', 'storage-and-consistency', 'Storage and Consistency', 'What a row actually is, what Postgres writes before it writes anything else, what cleans up after both of those, and what "replication" really moves under the hood.', 1),
  ('operation-be-database-mastery-2', 'campaign-be-database-mastery', 'indexes-and-operations', 'Indexes and Operations', 'The structures that let a query skip work it doesn''t need to do, and the operational tools and traps -- JSONB, advisory locks, queues, poolers, and the migration that started all of this -- that come with running Postgres for real.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-database-mastery-01', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-1', 'mvcc', 'MVCC', 'Two transactions touch the same row at the same second, and neither one blocks the other. Postgres doesn''t lock its way out of that -- it keeps more than one version of the row around at once.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"mvcc-sim"}'::jsonb, '{"xp":426,"credits":82}'::jsonb, false, 1),
  ('mission-be-database-mastery-02', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-1', 'wal-concepts', 'WAL Concepts', 'Every change to a Postgres table is written somewhere else first, before the table itself is touched. That somewhere else is the reason a crash mid-write doesn''t mean data loss.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"wal-concepts-sim"}'::jsonb, '{"xp":428,"credits":82}'::jsonb, false, 2),
  ('mission-be-database-mastery-03', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-1', 'vacuum-concepts', 'Vacuum Concepts', 'MVCC''s old row versions don''t disappear the moment nobody needs them anymore. Something has to go back and clean them up -- and when that something falls behind, the table pays for it in disk and speed.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"vacuum-concepts-sim"}'::jsonb, '{"xp":430,"credits":83}'::jsonb, false, 3),
  ('mission-be-database-mastery-04', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-1', 'replication-internals', 'Replication Internals', 'Act 32 covered replication and failover at the level of the system. This is the level below that: what Postgres is actually streaming, and what a "failover" really flips.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"replication-internals-sim"}'::jsonb, '{"xp":432,"credits":83}'::jsonb, false, 4),
  ('mission-be-database-mastery-05', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-1', 'partition-pruning', 'Partition Pruning', 'A sixty-partition table and a query that only needs one month of data. The planner doesn''t scan sixty partitions and throw away fifty-nine results -- it never opens them in the first place.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"partition-pruning-sim"}'::jsonb, '{"xp":434,"credits":84}'::jsonb, false, 5),
  ('mission-be-database-mastery-06', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-1', 'index-only-scans', 'Index-Only Scans', 'An index that already holds every column a query needs shouldn''t require touching the table at all. Most of the time, it doesn''t -- and the exceptions come down to one structure most people have never heard of.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"index-only-scans-sim"}'::jsonb, '{"xp":436,"credits":84}'::jsonb, false, 6),
  ('mission-be-database-mastery-07', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-2', 'partial-indexes', 'Partial Indexes', '49.97 million rows nobody ever queries again, and 30,000 that get hit constantly. Indexing all of them is indexing the wrong 99.94 percent.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"partial-indexes-sim"}'::jsonb, '{"xp":438,"credits":85}'::jsonb, false, 7),
  ('mission-be-database-mastery-08', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-2', 'jsonb', 'JSONB', 'A GIN index sits on the column, the query filters on that exact column, and Postgres still scans the whole table. The index and the query are speaking two different operators.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"jsonb-sim"}'::jsonb, '{"xp":440,"credits":85}'::jsonb, false, 8),
  ('mission-be-database-mastery-09', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-2', 'advisory-locks', 'Advisory Locks', 'A lock that isn''t attached to any row, any table, or any constraint -- just a number the application made up, and a guarantee Postgres will honor it anyway.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"advisory-locks-sim"}'::jsonb, '{"xp":442,"credits":86}'::jsonb, false, 9),
  ('mission-be-database-mastery-10', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-2', 'database-queues-when-not-to', 'Database Queues: When Not To', 'SELECT ... FOR UPDATE SKIP LOCKED turns any table into a passable job queue. "Passable" is the operative word, and there''s a throughput line where it stops being true.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"database-queues-when-not-to-sim"}'::jsonb, '{"xp":444,"credits":86}'::jsonb, false, 10),
  ('mission-be-database-mastery-11', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-2', 'connection-proxies', 'Connection Proxies', 'A pooler that hands out a thousand app connections from a dozen real ones sounds like a free win. It is, until something depends on a connection remembering who it belonged to a second ago.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"connection-proxies-sim"}'::jsonb, '{"xp":446,"credits":86}'::jsonb, false, 11),
  ('mission-be-database-mastery-12', 'world-be-database-mastery', 'campaign-be-database-mastery', 'operation-be-database-mastery-2', 'the-migration-that-didnt-feel-small', 'The Migration That Didn''t Feel Small', 'A one-line ALTER TABLE, reviewed and approved as low-risk, holds the production write path hostage for four minutes. Nobody on the team can explain why until they stop thinking about the SQL and start thinking about what it actually does to forty million rows.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-database-mastery-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"migration-that-didnt-feel-small-boss-sim"}'::jsonb, '{"xp":820,"credits":200,"badgeIds":["migration-that-didnt-feel-small"],"skillXp":{"database_internals":35}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be-database-mastery-01', 1, 'mira', 'Thirty-two Acts, and we never once opened up what Postgres is actually doing under a normal read and a normal write happening at the same time. Let''s fix that.'),
  ('mission-be-database-mastery-01', 2, 'forge', 'Two transactions, same row, same instant. Neither one blocks the other, and neither sees the other''s uncommitted change. Postgres pulls that off with MVCC -- multi-version concurrency control. A write doesn''t overwrite the row in place; it creates a new version of it.'),
  ('mission-be-database-mastery-01', 3, 'mira', 'Which means a "row" is really a chain of versions, and every transaction reads whichever version was visible at the moment its own snapshot started. Nothing about that requires blocking anybody.'),

  ('mission-be-database-mastery-02', 1, 'forge', 'Before Postgres changes a single byte of an actual table file, it writes a record of that change to the write-ahead log first. Every time. No exceptions.'),
  ('mission-be-database-mastery-02', 2, 'mira', 'Which sounds like extra work -- and it is -- but it''s the reason a crash mid-write doesn''t cost you the write. On restart, Postgres replays the WAL against the data files and gets back to exactly where it left off.'),
  ('mission-be-database-mastery-02', 3, 'forge', 'It''s also, not coincidentally, the exact mechanism physical replication streams. A standby isn''t copying tables. It''s replaying the same log the primary already wrote.'),

  ('mission-be-database-mastery-03', 1, 'mira', 'MVCC''s cost shows up here: every update and delete leaves the old row version behind, because some other transaction''s snapshot might still need to see it.'),
  ('mission-be-database-mastery-03', 2, 'forge', 'Autovacuum''s job is going back through and marking those old versions reclaimable once nothing can see them anymore. Fall behind on that, and a table doesn''t shrink -- it just keeps growing, forever, even if the live row count never changes.'),

  ('mission-be-database-mastery-04', 1, 'mira', 'You already know why a system replicates and what failover means from thirty-two Acts of practicing it under pressure. Today''s about what Postgres specifically is doing when it does that.'),
  ('mission-be-database-mastery-04', 2, 'forge', 'Physical replication ships the WAL, byte for byte, to a standby that''s a complete clone -- same version, same everything, every table, all the time. Logical replication decodes that same WAL into row-level changes and lets you pick tables, filter rows, even replicate to a different major version.'),
  ('mission-be-database-mastery-04', 3, 'mira', 'And failover isn''t Postgres deciding anything on its own. Something external -- an operator, a tool like Patroni -- has to promote a standby out of recovery mode. Postgres itself doesn''t vote.'),

  ('mission-be-database-mastery-05', 1, 'forge', 'Sixty monthly partitions under one table name, and a query asking for June only. Watch the plan: fifty-nine of those partitions never get opened.'),
  ('mission-be-database-mastery-05', 2, 'mira', 'The planner compares the query''s WHERE clause against each partition''s declared bounds before it ever executes anything. If a partition''s range provably can''t contain a match, it''s excluded from the plan -- not scanned and discarded, excluded.'),

  ('mission-be-database-mastery-06', 1, 'mira', 'An index on (customer_id, status) already contains everything a query selecting those two columns needs. In principle, Postgres never has to open the table at all.'),
  ('mission-be-database-mastery-06', 2, 'forge', 'In practice, it depends on the visibility map -- one bit per page, tracking whether every row on that page is guaranteed visible to everyone. If a page''s bit isn''t set, usually because it has recent changes vacuum hasn''t caught up to yet, Postgres has to go check the real row anyway.'),

  ('mission-be-database-mastery-07', 1, 'forge', 'Forty-nine point nine seven million completed jobs nobody will ever query again, and thirty thousand pending ones that get hit every few seconds. A full index on this table indexes the wrong rows almost entirely.'),
  ('mission-be-database-mastery-07', 2, 'mira', 'A partial index -- WHERE status = ''pending'' baked into the index definition itself -- only ever contains the hot subset. Small, cheap to maintain, and the planner will still reach for it automatically whenever a query''s filter matches the index''s own predicate.'),

  ('mission-be-database-mastery-08', 1, 'mira', 'JSONB stores parsed, binary JSON -- not text -- which is why containment queries against it can actually use an index instead of parsing on every row.'),
  ('mission-be-database-mastery-08', 2, 'forge', 'Default GIN index, though, is built for containment: does this document contain that structure. It is not built to make payload->>''type'' = ''login'' fast. Different operator, different index support, and the planner won''t pretend otherwise.'),

  ('mission-be-database-mastery-09', 1, 'forge', 'Every lock we''ve talked about so far belongs to something: a row, a table, a page. An advisory lock belongs to nothing except a number your application made up.'),
  ('mission-be-database-mastery-09', 2, 'mira', 'Which is exactly the point. It''s Postgres agreeing to enforce a mutex that has nothing to do with data -- "only one instance of this nightly job, cluster-wide" -- and a session-level one vanishes automatically if the connection dies, crash or not.'),

  ('mission-be-database-mastery-10', 1, 'mira', 'SELECT ... FOR UPDATE SKIP LOCKED is a genuinely good pattern -- multiple workers can grab different rows off a table without ever blocking each other.'),
  ('mission-be-database-mastery-10', 2, 'forge', 'At low volume. At real queue throughput, every claim is still an MVCC write, which means every claim leaves a dead tuple behind. The table you''re using as a queue starts needing the same vacuum attention as any other hot table, except now it''s also your bottleneck.'),

  ('mission-be-database-mastery-11', 1, 'forge', 'A transaction-mode pooler can hand a thousand app connections a real backend connection each, using a pool of maybe twenty actual Postgres connections, because it only holds the binding for the length of one transaction.'),
  ('mission-be-database-mastery-11', 2, 'mira', 'Which is also exactly what breaks anything that assumes a connection remembers something across transactions -- SET LOCAL outside a single transaction, a prepared statement from one call reused on the next. The backend you get next time might not be the one you had before.'),

  ('mission-be-database-mastery-12', 1, 'mira', 'The migration itself was one line. ALTER TABLE dispatch_events ADD COLUMN retry_token uuid NOT NULL DEFAULT gen_random_uuid();. Reviewed, approved, looked completely routine.'),
  ('mission-be-database-mastery-12', 2, 'forge', 'It locked the table for four minutes. Every read and every write to dispatch_events queued up behind it, on a table that does about six hundred writes a second.'),
  ('mission-be-database-mastery-12', 3, 'mira', 'Nobody on the review could explain afterward why a change that looked that small took the whole write path down with it. Walk through it with me -- not what the migration says, what it actually makes Postgres do to forty million existing rows.'),
  ('mission-be-database-mastery-12', 4, 'forge', 'Then design the version that doesn''t do that. And there''s a second piece to this one -- the index the team needed right after, which has the same shape of problem for a different reason.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be-database-mastery-01-o1', 'mission-be-database-mastery-01', 1, 'Explain how MVCC avoids blocking', 'Choose why two concurrent transactions can read and write the same table without blocking each other.'),
  ('mission-be-database-mastery-02-o1', 'mission-be-database-mastery-02', 1, 'Explain why data survives a crash', 'Choose why a committed change survives a crash even before its data page was written to disk.'),
  ('mission-be-database-mastery-03-o1', 'mission-be-database-mastery-03', 1, 'Diagnose runaway table bloat', 'Choose why a table keeps growing even though autovacuum is enabled and the live row count is stable.'),
  ('mission-be-database-mastery-04-o1', 'mission-be-database-mastery-04', 1, 'Tell physical and logical replication apart', 'Choose why physical replication can''t do a filtered, cross-version replication job, and what actually can.'),
  ('mission-be-database-mastery-05-o1', 'mission-be-database-mastery-05', 1, 'Explain why a partitioned query gets faster', 'Choose why the planner only scans one partition out of sixty for a date-bounded query.'),
  ('mission-be-database-mastery-06-o1', 'mission-be-database-mastery-06', 1, 'Explain when Postgres can skip the table', 'Choose what determines whether a given row still needs a heap fetch during an index-only scan.'),
  ('mission-be-database-mastery-07-o1', 'mission-be-database-mastery-07', 1, 'Choose the right index for a skewed dataset', 'Choose the index design that fits a table where almost all rows are cold and a tiny fraction is hot.'),
  ('mission-be-database-mastery-08-o1', 'mission-be-database-mastery-08', 1, 'Fix a JSONB query that skips the index', 'Debug a query against a GIN-indexed JSONB column that still forces a sequential scan.'),
  ('mission-be-database-mastery-09-o1', 'mission-be-database-mastery-09', 1, 'Choose the right locking primitive', 'Choose the locking mechanism that fits a cluster-wide mutex with no row or table behind it.'),
  ('mission-be-database-mastery-10-o1', 'mission-be-database-mastery-10', 1, 'Recognize when a table-as-queue stops scaling', 'Choose the actual bottleneck a SKIP LOCKED table queue runs into that a dedicated queue wouldn''t.'),
  ('mission-be-database-mastery-11-o1', 'mission-be-database-mastery-11', 1, 'Explain what a connection pooler trades away', 'Choose why session-level features misbehave behind a transaction-mode connection pooler.'),
  ('mission-be-database-mastery-12-o1', 'mission-be-database-mastery-12', 1, 'Diagnose the four-minute lock', 'Judge why this specific ALTER TABLE held an exclusive lock for the full four minutes.'),
  ('mission-be-database-mastery-12-o2', 'mission-be-database-mastery-12', 2, 'Design the zero-downtime version', 'Judge the correct way to add this column without blocking production traffic.'),
  ('mission-be-database-mastery-12-o3', 'mission-be-database-mastery-12', 3, 'Confirm the index-build corollary', 'Judge why the follow-up CREATE INDEX carries the same risk, and what avoids it.'),
  ('mission-be-database-mastery-12-o4', 'mission-be-database-mastery-12', 4, 'Close the migration', 'Synthesize the diagnosis, the column fix, and the index fix into one zero-downtime migration plan.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be-database-mastery-01-o1-c1', 'mission-be-database-mastery-01-o1', 1, 'multiple_choice', 'A long-running analytics query is reading orders while another transaction updates rows in the same table. The analytics query never blocks and never sees the update. Why?', '{"question":"A long-running analytics query is reading orders while another transaction updates rows in the same table. The analytics query never blocks and never sees the update. Why?","options":[{"id":"a","text":"Postgres takes a shared lock that blocks writers until the read finishes"},{"id":"b","text":"Postgres gives every transaction a consistent snapshot: writers create new row versions (tuples) instead of overwriting in place, so readers keep seeing the versions visible as of their snapshot while writers proceed independently"},{"id":"c","text":"Postgres queues all writes until every open read transaction commits"},{"id":"d","text":"The update is buffered in memory and never touches the table until the reader disconnects"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-database-mastery-02-o1-c1', 'mission-be-database-mastery-02-o1', 1, 'multiple_choice', 'Postgres commits a transaction and returns success to the client, then the server crashes before the changed data page is flushed to the table file on disk. After restart, the change is still there. Why?', '{"question":"Postgres commits a transaction and returns success to the client, then the server crashes before the changed data page is flushed to the table file on disk. After restart, the change is still there. Why?","options":[{"id":"a","text":"Postgres re-executes the original SQL statement from a query log after restart"},{"id":"b","text":"The change was already durably written to the write-ahead log (WAL) before commit acknowledged, and crash recovery replays the WAL against the data files on startup"},{"id":"c","text":"Postgres holds all committed data in a separate, always-synced shadow copy of every table"},{"id":"d","text":"The operating system''s page cache guarantees the write survived even without an explicit WAL"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-database-mastery-03-o1-c1', 'mission-be-database-mastery-03-o1', 1, 'multiple_choice', 'A table that should hold about 2 million live rows is occupying disk space consistent with 40 million rows, and query performance keeps degrading. Autovacuum is enabled. What''s the most likely explanation?', '{"question":"A table that should hold about 2 million live rows is occupying disk space consistent with 40 million rows, and query performance keeps degrading. Autovacuum is enabled. What''s the most likely explanation?","options":[{"id":"a","text":"Postgres never reclaims space from deleted rows under any circumstances"},{"id":"b","text":"A long-held open transaction (or replication slot) is preventing vacuum from removing dead tuples, because vacuum can never remove a row version that might still be visible to some still-open transaction''s snapshot"},{"id":"c","text":"The table needs a REINDEX, not a vacuum"},{"id":"d","text":"Autovacuum only runs once per day by default, which is too infrequent for any table"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-database-mastery-04-o1-c1', 'mission-be-database-mastery-04-o1', 1, 'multiple_choice', 'The team needs to replicate only two tables out of a fifty-table database into an analytics warehouse running a different major version of Postgres, while the primary keeps serving writes. Physical replication can''t do this. What''s the actual reason, and what should they use instead?', '{"question":"The team needs to replicate only two tables out of a fifty-table database into an analytics warehouse running a different major version of Postgres, while the primary keeps serving writes. Physical replication can''t do this. What''s the actual reason, and what should they use instead?","options":[{"id":"a","text":"Physical replication streams WAL records tied to the exact on-disk layout of the whole cluster, replaying every change to every table and requiring an identical Postgres version on the standby; logical replication decodes WAL into row-level changes and can replicate a subset of tables to a different, compatible Postgres version"},{"id":"b","text":"Physical replication is just slower than logical replication, so the fix is to add more replicas"},{"id":"c","text":"Logical replication doesn''t actually exist in Postgres; only third-party tools can filter which tables replicate"},{"id":"d","text":"The distinction is arbitrary -- both replicate at the exact same granularity"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-be-database-mastery-05-o1-c1', 'mission-be-database-mastery-05-o1', 1, 'multiple_choice', 'A table is range-partitioned by order_date, one partition per month, 5 years of data. A query filters WHERE order_date >= ''2026-06-01'' AND order_date < ''2026-07-01''. Even though the table has 60 partitions, the planner only scans one. Why?', '{"question":"A table is range-partitioned by order_date, one partition per month, 5 years of data. A query filters WHERE order_date >= ''2026-06-01'' AND order_date < ''2026-07-01''. Even though the table has 60 partitions, the planner only scans one. Why?","options":[{"id":"a","text":"Postgres always scans every partition but returns rows from only one, filtering client-side"},{"id":"b","text":"The planner can prove, from the partition bounds and the query''s WHERE clause, that every other partition''s date range cannot contain a matching row, so it excludes them from the plan entirely -- before execution even starts"},{"id":"c","text":"Partitioned tables automatically build a single combined index across all partitions, and the index handles filtering"},{"id":"d","text":"Only exact-equality filters trigger pruning; range filters always scan every partition"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-database-mastery-06-o1-c1', 'mission-be-database-mastery-06-o1', 1, 'multiple_choice', 'A query SELECT customer_id, status FROM orders WHERE customer_id = 42 has an index on (customer_id, status). EXPLAIN shows an Index Only Scan with zero heap fetches for most rows, but a few rows still show heap fetches. What determines whether a given row needs that extra heap fetch?', '{"question":"A query SELECT customer_id, status FROM orders WHERE customer_id = 42 has an index on (customer_id, status). EXPLAIN shows an Index Only Scan with zero heap fetches for most rows, but a few rows still show heap fetches. What determines whether a given row needs that extra heap fetch?","options":[{"id":"a","text":"Whether the row''s page is marked all-visible in the visibility map -- if it isn''t, usually because the page has recent, not-yet-vacuumed changes, Postgres must check the actual heap tuple to confirm visibility, even though every needed column exists in the index"},{"id":"b","text":"Whether the row was inserted more than a year ago"},{"id":"c","text":"Whether the query also selects a column not present in the index"},{"id":"d","text":"Index-only scans always need a heap fetch for every row; \"index only\" just means it doesn''t sort afterward"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-be-database-mastery-07-o1-c1', 'mission-be-database-mastery-07-o1', 1, 'multiple_choice', 'A jobs table has 50 million rows, 49.97 million of which are status = ''completed'' and effectively never queried again. The hot query is WHERE status = ''pending'' ORDER BY created_at, matching about 30,000 rows at any time. Which index is the better fit, and why?', '{"question":"A jobs table has 50 million rows, 49.97 million of which are status = ''completed'' and effectively never queried again. The hot query is WHERE status = ''pending'' ORDER BY created_at, matching about 30,000 rows at any time. Which index is the better fit, and why?","options":[{"id":"a","text":"A full btree index on (status, created_at), since a bigger index always improves performance"},{"id":"b","text":"A partial index -- CREATE INDEX ON jobs (created_at) WHERE status = ''pending'' -- it only indexes the tiny hot subset, stays small and cheap to maintain, and the planner can still use it because the query''s WHERE clause matches the index''s predicate"},{"id":"c","text":"No index at all, since Postgres already caches the whole table in memory"},{"id":"d","text":"A hash index on status alone"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-database-mastery-08-o1-c1', 'mission-be-database-mastery-08-o1', 1, 'code_debugging', 'This query never uses the new GIN index and keeps sequential-scanning the whole table. Which line is responsible?', '{"language":"sql","code":"create index idx_events_payload on events using gin (payload);\n\nselect * from events where payload->>''type'' = ''login'';","question":"This query never uses the new GIN index and keeps sequential-scanning the whole table. Which line is responsible?"}'::jsonb, '{"requiredLineIds":["select * from events where payload->>''type'' = ''login'';"]}'::jsonb),

  ('mission-be-database-mastery-09-o1-c1', 'mission-be-database-mastery-09-o1', 1, 'multiple_choice', 'A nightly batch job must ensure only one instance of itself runs at a time across multiple app servers, without locking any actual table row, and without leaving a lock behind if the process crashes -- the lock should simply vanish when the session ends. What''s the right tool?', '{"question":"A nightly batch job must ensure only one instance of itself runs at a time across multiple app servers, without locking any actual table row, and without leaving a lock behind if the process crashes -- the lock should simply vanish when the session ends. What''s the right tool?","options":[{"id":"a","text":"A regular row lock via SELECT ... FOR UPDATE on a dedicated locks table"},{"id":"b","text":"A Postgres advisory lock (pg_advisory_lock), taken on an arbitrary application-chosen key -- it isn''t tied to any row or table, and a session-level advisory lock is automatically released if the session or connection ends, even on a crash"},{"id":"c","text":"A unique constraint violation used as a mutex"},{"id":"d","text":"An application-level Redis lock, since Postgres has no concept of a lock that isn''t tied to a row"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-database-mastery-10-o1-c1', 'mission-be-database-mastery-10-o1', 1, 'multiple_choice', 'A team implements a job queue as a Postgres table, using SELECT ... FOR UPDATE SKIP LOCKED so multiple workers can grab jobs without blocking each other. It works fine at low volume. At high throughput, what''s the actual bottleneck this pattern runs into that a dedicated queue wouldn''t?', '{"question":"A team implements a job queue as a Postgres table, using SELECT ... FOR UPDATE SKIP LOCKED so multiple workers can grab jobs without blocking each other. It works fine at low volume. At high throughput, what''s the actual bottleneck this pattern runs into that a dedicated queue wouldn''t?","options":[{"id":"a","text":"SKIP LOCKED itself is unsafe and can hand the same row to two workers"},{"id":"b","text":"Every claimed job is still an MVCC write and leaves dead tuples behind, so at high throughput the table churns through vacuum work fast enough that bloat and index-maintenance overhead become the dominant cost -- on top of every worker''s poll being a real query competing for the same buffer and lock resources"},{"id":"c","text":"Postgres tables have a hard row-count limit far lower than any real queue''s throughput"},{"id":"d","text":"FOR UPDATE SKIP LOCKED requires a full table lock, so only one worker can ever poll at a time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-database-mastery-11-o1-c1', 'mission-be-database-mastery-11-o1', 1, 'multiple_choice', 'The team puts a transaction-mode connection pooler in front of Postgres to handle thousands of app connections with a small pool of real backend connections. Afterward, a feature relying on session-level state -- a prepared statement created on one call and reused later -- starts behaving inconsistently. Why?', '{"question":"The team puts a transaction-mode connection pooler in front of Postgres to handle thousands of app connections with a small pool of real backend connections. Afterward, a feature relying on session-level state -- a prepared statement created on one call and reused later -- starts behaving inconsistently. Why?","options":[{"id":"a","text":"The pooler silently drops 1% of queries at random"},{"id":"b","text":"In transaction-pooling mode, a client''s logical connection is only bound to a real backend connection for the duration of a single transaction -- the backend gets handed to a different client right after, so anything tied to session state instead of transaction state can vanish or leak across clients"},{"id":"c","text":"Connection poolers only support read queries, never writes"},{"id":"d","text":"Postgres itself forbids prepared statements when any proxy is in the connection path"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-database-mastery-12-o1-c1', 'mission-be-database-mastery-12-o1', 1, 'multiple_choice', 'The migration that locked the table for four minutes was: ALTER TABLE dispatch_events ADD COLUMN retry_token uuid NOT NULL DEFAULT gen_random_uuid();. The table has 40 million rows. What''s the actual reason this held an exclusive lock for the entire four minutes instead of returning instantly?', '{"question":"The migration that locked the table for four minutes was: ALTER TABLE dispatch_events ADD COLUMN retry_token uuid NOT NULL DEFAULT gen_random_uuid();. The table has 40 million rows. What''s the actual reason this held an exclusive lock for the entire four minutes instead of returning instantly?","options":[{"id":"a","text":"NOT NULL constraints always require an exclusive lock, regardless of the default"},{"id":"b","text":"gen_random_uuid() is a volatile, non-constant default, so Postgres cannot just record one static value in the catalog -- it must physically rewrite every one of the 40 million rows to compute and store a value for each, holding an ACCESS EXCLUSIVE lock that blocks all reads and writes for the full rewrite"},{"id":"c","text":"uuid columns are always slower to add than text columns"},{"id":"d","text":"The four minutes was actually spent building an index that wasn''t requested"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-database-mastery-12-o2-c1', 'mission-be-database-mastery-12-o2', 1, 'multiple_choice', 'What''s the correct way to add this column without blocking production traffic?', '{"question":"What''s the correct way to add this column without blocking production traffic?","options":[{"id":"a","text":"Add the column with a constant, non-volatile default (or no default) and no NOT NULL constraint first -- a fast, metadata-only catalog change -- then backfill the value in small batches, and only add the NOT NULL constraint afterward, e.g. via NOT VALID plus a separate VALIDATE CONSTRAINT, once every row has a value"},{"id":"b","text":"Just run it during off-peak hours -- the lock duration doesn''t change, only who notices"},{"id":"c","text":"Wrap the ALTER TABLE in a transaction so it can be rolled back if it''s too slow"},{"id":"d","text":"Add the column to a replica first, then promote the replica"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-database-mastery-12-o3-c1', 'mission-be-database-mastery-12-o3', 1, 'multiple_choice', 'Later in the same migration, a new index was needed on retry_token. The team wrote CREATE INDEX ON dispatch_events (retry_token);. Why is this also a hot-table risk, and what''s the fix?', '{"question":"Later in the same migration, a new index was needed on retry_token. The team wrote CREATE INDEX ON dispatch_events (retry_token);. Why is this also a hot-table risk, and what''s the fix?","options":[{"id":"a","text":"Plain CREATE INDEX takes a lock that blocks concurrent writes to the table for the entire index build; CREATE INDEX CONCURRENTLY builds the index in the background with a weaker lock, at the cost of taking longer and not running inside a transaction block"},{"id":"b","text":"Indexes never block anything; the risk is purely disk space"},{"id":"c","text":"CREATE INDEX CONCURRENTLY is strictly worse and should be avoided in production"},{"id":"d","text":"The fix is to build the index on a replica and it magically appears on the primary"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-database-mastery-12-o4-c1', 'mission-be-database-mastery-12-o4', 1, 'boss_encounter', 'Having diagnosed the lock, designed the zero-downtime column fix, and confirmed the index-build corollary, state the full migration plan.', '{"stages":[{"objectiveRef":"mission-be-database-mastery-12-o1","label":"Diagnose the four-minute lock"},{"objectiveRef":"mission-be-database-mastery-12-o2","label":"Design the zero-downtime version"},{"objectiveRef":"mission-be-database-mastery-12-o3","label":"Confirm the index-build corollary"}],"task":"Having diagnosed the lock, designed the zero-downtime column fix, and confirmed the index-build corollary, state the full migration plan: add retry_token without a volatile default and without NOT NULL (fast, metadata-only), backfill it in batches, add NOT NULL via NOT VALID plus a separate VALIDATE CONSTRAINT once every row is backfilled, and build the new index with CREATE INDEX CONCURRENTLY -- none of those steps ever holds a long exclusive lock on the live table."}'::jsonb, '{"requiredObjectiveIds":["mission-be-database-mastery-12-o1","mission-be-database-mastery-12-o2","mission-be-database-mastery-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be-database-mastery-01-o1-c1', 'orientation', 'Think about what a "version" of a row buys you that a lock doesn''t.', 15, 1),
  ('mission-be-database-mastery-01-o1-c1', 'solution', 'b: Postgres creates a new row version on write instead of overwriting in place, so each transaction''s snapshot just reads whichever version was visible when it started -- no blocking required.', 30, 2),

  ('mission-be-database-mastery-02-o1-c1', 'orientation', 'The client got "success" before the crash. Ask what had to already be durable for that to be a true statement.', 15, 1),
  ('mission-be-database-mastery-02-o1-c1', 'solution', 'b: the WAL record was flushed to disk before commit acknowledged; crash recovery replays the WAL against the data files on restart, reproducing the change even though the data page itself hadn''t been written yet.', 30, 2),

  ('mission-be-database-mastery-03-o1-c1', 'orientation', 'Autovacuum being enabled doesn''t guarantee it can finish its job. Ask what would stop it from removing a dead row version even though it wants to.', 15, 1),
  ('mission-be-database-mastery-03-o1-c1', 'solution', 'b: a long-open transaction or a replication slot holds back the oldest snapshot vacuum has to respect -- it can''t remove any row version that snapshot might still need, no matter how long ago the row was actually superseded.', 30, 2),

  ('mission-be-database-mastery-04-o1-c1', 'orientation', 'One of these replicates at the WAL/byte level; one decodes that WAL into row changes you can filter and route.', 15, 1),
  ('mission-be-database-mastery-04-o1-c1', 'solution', 'a: physical replication ships the exact WAL for the whole cluster to an identical-version standby; logical replication decodes it into row-level changes, so it can replicate a subset of tables across compatible-but-different major versions.', 30, 2),

  ('mission-be-database-mastery-05-o1-c1', 'orientation', '"Scanned and discarded" and "never opened" are two very different plans -- check which one the planner actually produces.', 15, 1),
  ('mission-be-database-mastery-05-o1-c1', 'solution', 'b: the planner compares the query''s bounds to each partition''s declared range before execution and drops any partition that provably can''t match, so only the one relevant partition is ever touched.', 30, 2),

  ('mission-be-database-mastery-06-o1-c1', 'orientation', 'Every needed column being in the index is necessary but not sufficient -- there''s one more structure Postgres checks per page.', 15, 1),
  ('mission-be-database-mastery-06-o1-c1', 'solution', 'a: the visibility map tracks, per page, whether every row on it is guaranteed visible to all transactions; if that bit isn''t set, Postgres still has to check the heap tuple even though the index already had the data.', 30, 2),

  ('mission-be-database-mastery-07-o1-c1', 'orientation', 'A full index would faithfully index 49.97 million rows nobody ever asks for again. Ask what a smaller, targeted index buys instead.', 15, 1),
  ('mission-be-database-mastery-07-o1-c1', 'solution', 'b: a partial index restricted to WHERE status = ''pending'' only ever contains the small hot subset, stays cheap to maintain, and the planner uses it automatically whenever a query''s filter matches its predicate.', 30, 2),

  ('mission-be-database-mastery-08-o1-c1', 'orientation', 'A GIN index built for containment (@>) doesn''t automatically make every kind of JSONB query fast -- check what operator the query is actually using.', 15, 1),
  ('mission-be-database-mastery-08-o1-c1', 'solution', 'The select statement uses payload->>''type'' = ''login'', a text-extraction-and-equality comparison the default GIN index can''t satisfy; either query with payload @> ''{"type": "login"}''::jsonb, or add a plain btree expression index on (payload->>''type'').', 30, 2),

  ('mission-be-database-mastery-09-o1-c1', 'orientation', 'Rule out anything that requires a row, a table, or a constraint to exist -- the lock here is attached to none of those.', 15, 1),
  ('mission-be-database-mastery-09-o1-c1', 'solution', 'b: pg_advisory_lock takes a lock on an arbitrary application key, not on any row or table, and a session-level advisory lock is released automatically the moment the session ends, crash or not.', 30, 2),

  ('mission-be-database-mastery-10-o1-c1', 'orientation', 'SKIP LOCKED solves the blocking problem between workers. Ask what claiming a job actually costs Postgres under the hood.', 15, 1),
  ('mission-be-database-mastery-10-o1-c1', 'solution', 'b: every claim is an MVCC write that leaves a dead tuple behind, so at high throughput the queue table needs the same vacuum and index-maintenance attention as any hot table -- and polling itself becomes real query load competing for the same resources.', 30, 2),

  ('mission-be-database-mastery-11-o1-c1', 'orientation', 'The pooler''s whole trick is not holding a backend connection open for a client any longer than it has to. Ask what that costs you.', 15, 1),
  ('mission-be-database-mastery-11-o1-c1', 'solution', 'b: in transaction-pooling mode a backend connection is only bound to a client for one transaction and then handed to someone else, so anything tied to session state instead of transaction state can disappear or leak across clients.', 30, 2),

  ('mission-be-database-mastery-12-o1-c1', 'orientation', 'gen_random_uuid() doesn''t return the same value twice -- ask what that means for a column-wide default applied to every row.', 15, 1),
  ('mission-be-database-mastery-12-o1-c1', 'solution', 'b: a volatile default can''t be recorded once in the catalog, so Postgres must compute and write a value into every one of the 40 million rows, holding an ACCESS EXCLUSIVE lock for the entire rewrite.', 30, 2),
  ('mission-be-database-mastery-12-o2-c1', 'orientation', 'Split this into three separate steps instead of one ALTER TABLE, and ask which of those steps is actually slow.', 15, 1),
  ('mission-be-database-mastery-12-o2-c1', 'solution', 'a: add the column with no default (or a constant one) and no NOT NULL first -- a fast, catalog-only change -- backfill in small batches, then add NOT NULL via NOT VALID plus a separate VALIDATE CONSTRAINT once every row has a value.', 30, 2),
  ('mission-be-database-mastery-12-o3-c1', 'orientation', 'One of these two CREATE INDEX forms builds in the background with a weaker lock; the other doesn''t.', 15, 1),
  ('mission-be-database-mastery-12-o3-c1', 'solution', 'a: CREATE INDEX CONCURRENTLY avoids blocking concurrent writes for the whole build, at the cost of a longer build and not running inside a transaction block -- the plain CREATE INDEX does not have that concurrency.', 30, 2),
  ('mission-be-database-mastery-12-o4-c1', 'orientation', 'Put the rewrite diagnosis, the expand-and-backfill fix, and the concurrent-index note together into one migration plan.', 20, 1),
  ('mission-be-database-mastery-12-o4-c1', 'solution', 'Add the column without a volatile default and without NOT NULL (fast, metadata-only), backfill retry_token in batches, add NOT NULL via NOT VALID plus VALIDATE CONSTRAINT once backfilled, and build any new index with CREATE INDEX CONCURRENTLY -- none of those steps ever holds a long exclusive lock on the live table.', 35, 2);
